mapper.insert:
INSERT INTO herb_ai_knowledge_chunk (
    doc_id, chunk_index, chunk_title, chunk_content, content_hash,
    token_count, embedding_status, vector_id, metadata_json,
    create_time, update_time, is_deleted
) VALUES (
    #{docId}, #{chunkIndex}, #{chunkTitle}, #{chunkContent}, #{contentHash},
    #{tokenCount}, #{embeddingStatus}, #{vectorId}, #{metadataJson},
    #{createTime}, #{updateTime}, #{deleted}
)

mapper.select:
SELECT id, doc_id, chunk_index, chunk_title, chunk_content, content_hash, token_count, embedding_status, vector_id, metadata_json, create_time, update_time FROM herb_ai_knowledge_chunk WHERE doc_id = #{docId} AND is_deleted = 0
AND embedding_status = #{query.embeddingStatus}
ORDER BY chunk_index ASC, id ASC

SELECT c.doc_id, d.doc_title, c.id AS chunk_id, c.chunk_index, c.chunk_content AS content_preview FROM herb_ai_knowledge_chunk c INNER JOIN herb_ai_knowledge_doc d ON d.id = c.doc_id WHERE c.is_deleted = 0 AND d.is_deleted = 0 AND d.status = 'enabled' AND c.chunk_content LIKE CONCAT('%', #{keyword}, '%')
AND d.doc_type = #{docType}
ORDER BY c.update_time DESC, c.id DESC LIMIT #{limit}

mapper.update:
UPDATE herb_ai_knowledge_chunk
SET embedding_status = #{embeddingStatus},
    vector_id = #{vectorId},
    update_time = #{updateTime}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE herb_ai_knowledge_chunk
SET embedding_status = #{embeddingStatus},
    vector_id = NULL,
    update_time = #{updateTime}
WHERE doc_id = #{docId}
  AND is_deleted = 0

UPDATE herb_ai_knowledge_chunk
SET is_deleted = 1, update_time = #{updateTime}
WHERE doc_id = #{docId} AND is_deleted = 0
